<?php
namespace App\Services\Workflow;
use App\Support\Database;use App\Support\TenantContext;use App\Support\Auth;use App\Services\{ActivityService,DeadlineEngine,ExceptionEngine};
final class WorkflowEngine { public function start(int $projectId,int $versionId,?int $clientServiceId=null):int{$pdo=Database::pdo();$s=$pdo->prepare('INSERT INTO workflow_executions(tenant_id,project_id,workflow_version_id,status,started_at,created_at) VALUES(?,?,?,?,NOW(),NOW())');$s->execute([TenantContext::id(),$projectId,$versionId,'in_progress']);$id=(int)$pdo->lastInsertId();$q=$pdo->prepare('SELECT * FROM workflow_steps WHERE tenant_id=? AND workflow_version_id=? ORDER BY sort_order');$q->execute([TenantContext::id(),$versionId]);$i=$pdo->prepare('INSERT INTO workflow_step_executions(tenant_id,workflow_execution_id,workflow_step_id,status) VALUES(?,?,?,?)');foreach($q as $step)$i->execute([TenantContext::id(),$id,$step['id'],$step['requirement']==='optional'?'skipped':'not_started']);if($clientServiceId)(new DeadlineEngine)->generateForWorkflow($id,$clientServiceId);(new ActivityService)->log('workflow','started','workflow_execution',$id);return $id;}
 public function completeStep(int $executionId,int $stepId,array $value=[]):void{$pdo=Database::pdo();$s=$pdo->prepare("UPDATE workflow_step_executions SET status='completed',value_json=?,completed_by=?,completed_at=NOW() WHERE tenant_id=? AND workflow_execution_id=? AND workflow_step_id=? AND status IN ('not_started','in_progress')");$s->execute([json_encode($value),Auth::id(),TenantContext::id(),$executionId,$stepId]);if(!$s->rowCount())throw new \RuntimeException('Workflow step cannot be completed in its current state');$this->advance($executionId);}
 public function skipStep(int $executionId,int $stepId,string $reason=''):void{$s=Database::pdo()->prepare("UPDATE workflow_step_executions SET status='skipped',value_json=? WHERE tenant_id=? AND workflow_execution_id=? AND workflow_step_id=? AND status='not_started'");$s->execute([json_encode(['reason'=>$reason]),TenantContext::id(),$executionId,$stepId]);$this->advance($executionId);}
 private function advance(int $executionId):void{$pdo=Database::pdo();$s=$pdo->prepare("SELECT COUNT(*) FROM workflow_step_executions WHERE tenant_id=? AND workflow_execution_id=? AND status IN ('not_started','in_progress')");$s->execute([TenantContext::id(),$executionId]);if((int)$s->fetchColumn()===0){$u=$pdo->prepare("UPDATE workflow_executions SET status='completed',completed_at=NOW() WHERE tenant_id=? AND id=?");$u->execute([TenantContext::id(),$executionId]);} }
 public function fail(int $executionId,string $reason):void{(new ExceptionEngine)->raise('workflow_failure','Workflow failed',$reason,null,null,$executionId,'high');$s=Database::pdo()->prepare("UPDATE workflow_executions SET status='failed' WHERE tenant_id=? AND id=?");$s->execute([TenantContext::id(),$executionId]);}
}
